from mk import mk
mk("SfqgigefIu0","KARPLUS-STRONG synthesis in Renoise and the •REZONATOR•",
 "tuned-filtered-delay-resonator-insert-bipolar-feedback",
 "Filtered feedback-delay resonator: bipolar feedback, swappable loop filter type, dry mute, insert on existing sounds",
 "Turn a single filtered feedback delay into a playable 'renegade' Karplus-Strong voice and a resonator insert: impulse (noise burst or fast sine sweep, no loop) into a ~1–24 ms delay with feedback limited to ±99% (negative = hollow/odd-harmonic, positive = brighter), macro the in-loop filter type (LP/HP/BP/notch, with resonance on BP/notch) and cutoff as timbre controls, mute the dry click, map keys inversely onto delay time (long = low), then reuse the same delay as a metallic-body resonator on basses/pads — the delta beyond our key-tracked KS pluck skill is bipolar feedback polarity, loop-filter-type morphing, dry-mute and the resonator-insert use.",
 ["Delay with feedback and an in-loop filter (or DelayNode + BiquadFilter in a feedback loop / AudioWorklet)","An impulse source: short noise burst or fast high-to-low sine sweep","Optional macro controls / automation"],
 [("impulse","audio","Very short full-spectrum impulse (noise burst or sine sweep), not looped",True),("source_sound","audio","Existing bass/pad to resonate when used as an insert",False)],
 [("ks_tone","audio","Pitched/atonal string-like or metallic resonant tone"),("resonated_sound","audio","Source with added metallic-chamber body")],
 ["Feedback is capped at ±99% to avoid runaway self-oscillation.","Delay-line pitch changes glide (rubber-band portamento) — inherent, use it musically.","Web Audio: a feedback DelayNode cannot go below one render quantum (128 samples, ~2.7 ms @48k) — use an AudioWorklet delay for high pitches (implementation note, not transcript content).","Negative-feedback = polarity-inverted loop; transcript describes it as more square-like vs saw-like for positive."],
 [("Prepare a full-frequency impulse: a short white-noise burst or a fast sine sweep from very high to low frequency. Set it to one-shot (no loop) so it is only a click.","impulse","A transient click alone"),
  ("Insert a delay with feedback and an in-loop filter. Start around 24 ms delay, feedback 50%, effect amount full, filter low-pass fully open.","delay","Pitched ringing tone appears from the click"),
  ("Make performance macros: (1) L+R feedback with range −99…+99 (centre = almost no repeats; negative = hollow square-like character; positive = saw-like), (2) delay time L+R capped at ~24 ms as 'pitch', (3) filter cutoff.","macros","Feedback near ±99 gives long tails without running away; cutoff changes timbre/pitch character"),
  ("For keyboard pitch: map key tracking onto delay time inversely — lowest key → ~24 ms (slow cycle = low pitch), highest key → ~1 ms.","key-track","Higher keys give higher pitch, with a slight glide between notes"),
  ("Add a macro for filter type (LP/HP/BP/notch) and automate/record it. With bandpass or notch, raise resonance somewhat — they sound better slightly resonant.","loop-filter","Distinct resonant timbres per filter type; notch visible on a spectrogram"),
  ("Mute the dry signal so the impulse click disappears and only the resonance remains; optionally add drive in the loop (can scream) and a following delay.","mix","Clean resonant tone without the leading click; harmonics grow with drive"),
  ("Try different impulse sources (sine, saw, more or less pitched) — the impulse strongly changes the timbre.","impulse","Timbral variety from the same delay setting"),
  ("Resonator insert: put the same delay (wrapped in a macro rack) on an existing bass or pad; tune delay/filter to taste (check filter isn't left on high-pass), keep it subtle or brighter/distorted.","insert","Source gains a metallic-chamber body, depth and presence — reverb-like but resonant"),
  ("Resample interesting results for further processing.","resample","Printed resonant one-shots/textures")],
 ["With dry muted, a single impulse yields a pitched/resonant tail and no click.","Flipping feedback sign audibly changes the harmonic character (hollower when negative).","Changing delay time shifts pitch; key mapping is inverted (long delay = low).","Resonator insert on a bass adds audible metallic body vs bypass."],
 ["karplus-strong","delay","resonator","feedback","comb","filter","web-audio"])

mk("0n23itgG0LU","80s String Pad Tutorial (1/2) - Pulse Width Modulation in Tyrell N6",
 "pwm-80s-string-pad-free-running-lfo-detune",
 "80s PWM string pad: pulse wave with free-running (seconds-based) LFO on pulse width, slight osc-2 detune, slow attack/release, static filter",
 "Build a classic 1980s string pad from an init patch: switch the oscillator from saw to pulse, modulate pulse width from an LFO set in seconds (free-running, ~0.7, not tempo-synced so the ensemble rate never changes with song tempo), blend a second oscillator ever so slightly detuned, low-pass to remove the very high end with the filter envelope and other filter mod sources switched off, slow fade-in attack and long release — a dedicated PWM string pad distinct from our PW drone and unison string-section skills.",
 ["Two-oscillator subtractive synth with pulse wave + PW modulation (or Web Audio PeriodicWave/pulse via two offset saws)","LFO with free-running (Hz/seconds) mode","Low-pass filter, ADSR"],
 [("chords","midi","Sustained chords",True),("lfo_rate","number","PW LFO rate in seconds/Hz (presenter ~0.7)",False)],
 [("pwm_string_pad","audio","Warm fading 80s-style string pad")],
 ["Values are the presenter's display units, set by ear ('use your ears'); treat as starting points.","Reverb and EQ are covered in the follow-up video (not this transcript).","Web Audio: PWM can be made by subtracting a phase-shifted saw from a saw and modulating the delay/offset with an LFO (implementation note)."],
 [("Start from an init patch; keep a scope visible. Change oscillator 1 from saw to pulse (square = 50% duty cycle; pulse widths roughly 10–90% duty).","osc-1","Hollow square tone; scope shows pulse"),
  ("Route an LFO to pulse width and watch the scope: the pulse width sweeps.","pwm","Chorused, moving string-like tone"),
  ("Switch the PW LFO from tempo-sync to free-running seconds so the string movement keeps the same rate regardless of DAW tempo; set ~0.7 and a moderate depth.","lfo","Steady, natural ensemble movement"),
  ("Bring in oscillator 2 (presenter's level ~17.5) alongside osc 1, then detune osc 2 ever so slightly (fine ~0.20) — perfectly in-tune oscillators lose the effect.","osc-2","Beating/thickening between oscillators"),
  ("Lower the low-pass cutoff to cut the really high end; reduce output level if hot.","filter","Softer, darker strings"),
  ("Amp envelope: much slower attack (presenter ~38 display units) for a fade-in and a long release that tails naturally.","amp-env","Pad fades in and rings out smoothly"),
  ("Set master transpose from −12 to 0 so A440 plays A440. Turn off the filter envelope and other filter modulation sources so the filter stays static.","global","Correct pitch; no filter 'wah' on note-on"),
  ("Set the voice/unison count the presenter uses (2), play chords to confirm the 1980s string pad, and save it as a patch.","voices","Saved PWM string pad")],
 ["Scope shows pulse width moving when the LFO is active.","Changing DAW tempo does not change the PWM rate.","Setting osc-2 detune back to 0 noticeably flattens the pad.","Notes fade in and release slowly with no filter envelope sweep."],
 ["pwm","pulse-width","string-pad","pad","lfo","detune","80s","web-audio"])

mk("NFWAC2kLqvo","How to make your own Buchla Style Morphing Filter in VCV",
 "six-pole-bandpass-stepped-freq-bandwidth-snapshot-morph",
 "Buchla 291-style morphing bandpass: 6-pole bandpass with two clocked step sequencers (frequency and bandwidth) as filter snapshots, wet/dry crossfader",
 "Build a free West-Coast-style morphing filter: a steep 6-pole bandpass (bandwidth instead of resonance) fed a harmonically rich complex oscillator, with two clocked, randomized 8-step sequencers — one on frequency (v/oct, ±10 V) and one on bandwidth (0–10 V) — so each clock step jumps to a new 'filter snapshot', blended with the dry signal on a crossfader like an aux, plus optional LFO on the main frequency; copy the voice for a triple morphing filter.",
 ["Multimode filter with selectable slope (6-pole) and bandpass bandwidth control (Web Audio: cascade 3 bandpass BiquadFilterNodes, implementation note)","Two step sequencers with settable output ranges, a clock","Crossfader / wet-dry mixer","Harmonically rich source (complex oscillator / FM)"],
 [("source","audio","Complex/harmonically rich oscillator (a plain sine disappears in a bandpass)",True),("clock","trigger","Clock that advances the sequencers",True)],
 [("morphing_filter_voice","audio","Stepped, snapshot-morphing bandpass texture")],
 ["Pure sine sources vanish through a narrow bandpass — make the source complex/brighter first.","Sequencer ranges matter: frequency bipolar ±10 V, bandwidth unipolar 0–10 V (scale to Hz/Q in other environments).","FM/AM/ring-mod inputs of the hardware 291e are not reproduced here; only one mode at a time in this build."],
 [("Choose a multimode filter, set it to bandpass and the slope to 6 poles (type the value precisely); set bandwidth to 100%.","filter","Steep bandpass response"),
  ("Feed a complex oscillator; brighten/complexify it and raise the pitch until the bandpass has harmonics to work with. Sweep bandwidth to hear the change.","source","Clearly audible bandpass sweep"),
  ("Add two step sequencers: one to filter frequency (v/oct), output range ±10 V; one to bandwidth, range 0–10 V.","sequencer","Two control lanes ready"),
  ("Put a crossfader after the filter: filtered signal on A, dry signal on B, so the filter acts like an aux/wet-dry morph.","mix","Blend between filtered and dry"),
  ("Clock both sequencers, randomize all steps, set 8 steps forward, and run: each step recalls a different frequency+bandwidth 'snapshot'.","clock","Rhythmic jumps between distinct filter snapshots"),
  ("Adjust main frequency/bandwidth controls live and optionally modulate main frequency with an LFO via CV.","lfo","Further variety on top of the stepped snapshots"),
  ("For a triple morphing filter, duplicate the whole voice (filter + two sequencers) and offset settings.","duplicate","Three interleaved morphing bandpass voices")],
 ["Each clock step audibly changes both centre frequency and bandwidth.","Crossfader at B gives the dry source; at A the full filtered sound.","With a pure sine source the effect is weak — confirming the need for a rich source."],
 ["bandpass","buchla","west-coast","sequencer","filter-snapshot","morph","modular","web-audio"])

mk("-oFbaWsScJw","Trance Atmosphere Tutorial using Reverb Freeze 🥶",
 "reverb-freeze-print-seamless-loop-atmos-layer",
 "Reverb-freeze atmosphere print: freeze a 100%-wet reverb of a synth phrase, record it to audio, loop it seamlessly with overlapping tail, bus and process as an atmos layer",
 "Create a background atmosphere layer from any melodic synth part: send it to a 100%-wet, low-cut, high-diffusion/large-size/long-decay reverb with a freeze/hold function, engage freeze while the phrase plays, record the frozen output via a group bus onto a new audio track, then EQ it, add sidechain-style volume ducking and a second ~5–6 s reverb so the loop point is masked, duplicate and overlap the clips with a short end fade for a click-free endless loop, and group the layers into an atmos bus — optionally printing separate closed-filter and open-filter freezes to follow the arrangement.",
 ["Reverb with freeze/hold (Web Audio: ConvolverNode with long IR is not freezable — use a feedback-delay network with feedback = 1 and input muted, implementation note)","Bus/group routing and an audio track that can record a bus","EQ, volume-shaper/sidechain tool, second reverb"],
 [("phrase","audio","Synth melody/chord phrase to freeze",True)],
 [("atmos_loop","audio","Endless frozen-reverb atmosphere layer(s)")],
 ["DAW-specific routing (group → audio input) is generic: any bus-record or bounce works.","Keep faders out of the very bottom of their travel; add gain staging instead for fine balance.","Frozen print captures the filter state at freeze time — print separate states if the source filter opens later."],
 [("Insert a freeze-capable reverb on (or as a send for) the synth phrase: cut the lows, mix 100% wet, raise diffusion, size and decay.","reverb","Long dense wash of the phrase"),
  ("Play the phrase and engage freeze at the musically richest moment; the reverb holds indefinitely even when playback stops. Release/turn down to end.","freeze","Sustained frozen chord-cloud"),
  ("Route the synth (with the freezing reverb) to a dedicated group bus, create an audio track whose input is that bus, and record a few bars (~4) of the frozen output. Then remove the temporary reverb and restore the synth's original output routing.","record","Audio clip containing only the frozen ambience"),
  ("On the printed track: EQ low end out and tame highs; add a sidechain-style volume shaper so it pumps with the groove.","eq","Atmos sits behind the mix"),
  ("Add a second reverb on the print (low cut, ~5–6 s decay, larger size, modulation off) so the restart of the loop isn't heard as a jump.","reverb-2","Loop seam smeared"),
  ("Make the clip loop seamlessly: add a small fade at the end, duplicate it onto a second track, and overlap clips so each new clip starts while the previous tail fades.","loop","Endless loop with no clicks or pops"),
  ("Group both print tracks into an 'atmos' bus; process together (more freeze-able large reverb with lows cut ~600–700 Hz and reduced feedback/mix, gentle top-end saturation/exciter).","bus","Single controllable atmos layer"),
  ("If the source filter opens later in the arrangement, print a second freeze with the filter open and use closed/open layers per section.","arrangement","Atmos follows the arrangement's brightness")],
 ["Muting the original synth leaves a continuous bed that never stops.","Loop boundary is inaudible (no click or jump).","Atmos bus has low end removed (spectrum check below a few hundred Hz)."],
 ["reverb-freeze","freeze","atmosphere","ambience","print","loop","trance","web-audio"])

mk("4fpZFYG83fw","Ableton Sound Design Tutorial - Distorted Delays",
 "distorted-delay-return-bandlimited-send-throws",
 "Distorted-delay return: drive → ping-pong delay on a 100%-wet send, both band-limited to high mids, return pre-attenuated, played by riding the send",
 "Add crunchy, wide echo throws to a lead/pluck without mud or volume spikes: on a send/return insert drive then ping-pong delay, band-limit both to the high mids so lows aren't delayed, feedback ~56%, both 100% wet; dial drive/tone at maximum send, then pull the return down ~−6 dB as a safety ceiling, and perform/draw send-level automation so only chosen notes throw distorted echoes — the delta vs our ping-pong delay skill is drive-before-delay on a return and send-throw performance.",
 ["Send/return bus","Overdrive/distortion with a pre-filter band (or Biquad bandpass → WaveShaper)","Ping-pong delay with a filter"],
 [("lead","audio","Lead/pluck melody on its own track",True)],
 [("delay_throws","audio","Selective distorted ping-pong echoes")],
 ["Keep low mids out of the delay — delayed low mids muddy the track.","Return set at about −6 dB before dialing tone avoids level spikes when the send is maxed."],
 [("Create a spare return. Insert overdrive then delay (ping-pong).","return","Return chain ready"),
  ("Set the overdrive's pre-filter to the high mids only, and do the same on the delay's filter so only that band is delayed.","filter","Echoes crunch in the high mids, low mids untouched"),
  ("Delay: ping-pong for width, feedback ~56%; both devices 100% wet so only effect signal returns.","delay","Wide bouncing repeats"),
  ("Turn the send to maximum and dial drive and tone to the desired timbre.","drive","Character of the distorted echoes set"),
  ("Pull the return fader down (~−6 dB start) so maxed sends never produce super-loud output.","gain","Safe ceiling"),
  ("Perform: jam the send knob live to feel where echoes should happen, then tidy or draw send automation per note (some full, some partial).","automation","Only chosen notes throw distorted echoes"),
  ("Check in context with the full track and adjust.","mix","Echoes add interest without masking the lead")],
 ["With send at zero, the lead is completely dry.","Echoes contain little low-mid energy (spectrum check).","Maxing the send doesn't spike output above the dry lead's level."],
 ["delay","distortion","ping-pong","send-return","automation","throws","web-audio"])

mk("k9ZURoAww0k","Wavefolding LFO's in VCV Rack to make interesting wobble effects and unique waves Synth Sound Design",
 "wavefolded-lfo-slew-filter-wobble",
 "Wavefolded LFO wobble: fold a sine LFO for extra peaks/valleys, then slew-limit it before filter cutoff",
 "Make complex but smooth filter wobbles by running a plain sine LFO through a wavefolder (fold amount, symmetry, fold shape add peaks and valleys) before it reaches filter cutoff, then put a slew limiter after the folder so the folded modulation is less jumpy — a modulation-shaping recipe distinct from audio-rate wavefolding.",
 ["LFO, wavefolder accepting a control signal (Web Audio: WaveShaperNode on an LFO signal, implementation note), slew limiter / one-pole smoother, filter"],
 [("lfo","control","Sine LFO",True),("audio","audio","Sound into the filter",True)],
 [("wobble_filter","audio","Filter moved by a folded, slewed LFO")],
 ["Transcript is short (≈380 words); amounts are by ear, no numeric settings given.","Folded LFO at fast rates becomes jumpy — slow it down or slew it."],
 [("Baseline: route a regular sine LFO to filter cutoff and listen.","lfo","Plain wobble"),
  ("Insert a wavefolder between LFO and filter cutoff; compare the folded and plain sine on a scope.","wavefolder","Folded sine shows extra peaks and valleys; wobble becomes more complex"),
  ("Slow the LFO down (folding multiplies apparent rate) and adjust fold amount, symmetry and fold shape.","wavefolder","Different repeating wobble patterns per setting"),
  ("Add a slew limiter after the wavefolder, before the cutoff input, to soften the jumps.","slew","Smoother, less jumpy complex modulation")],
 ["Scope shows more peaks per cycle after the folder than before.","Increasing slew audibly smooths jumps without removing the extra contour."],
 ["wavefolder","lfo","slew","modulation-shaping","filter","modular","web-audio"])
